            parameters = this.omit(parameters, new ArrayList<Object>(Arrays.asList("triggerPrice", "stopPrice", "clientOrderId")));
            Map<String, Object> response = (this.privatePostMarketOrdersAdd(this.extend(request, parameters))).join();
